<template><view :class="['app-page',{dark}]"><ui-header title="提现记录" back/><view v-if="records.length" class="record-list"><view v-for="item in records" :key="item.id" class="record-card" @tap="open(item)"><view><text class="record-no">{{item.withdrawalNo}}</text><text class="muted">{{formatTime(item.createdAt)}}</text></view><view><text class="price">¥{{money(item.amount)}}</text><text :class="['status','status-'+item.status]">{{status(item.status)}}</text></view></view></view><ui-page-status v-else :loading="loading" title="暂无提现记录" :description="error" @retry="load"/></view></template>
<script>import{api}from'@/services/api';import{isDark}from'@/utils/app';export default{data(){return{dark:false,loading:true,error:'',records:[]}},onShow(){this.dark=isDark();this.load()},methods:{formatTime(v){return this.displayDateTime(v)},money(v){return Number(v||0).toFixed(2)},status(v){return({pending:'审核中',approved:'已通过',rejected:'已驳回',paid:'已完成'})[v]||v},async load(){this.loading=true;this.error='';try{this.records=await api.getWithdrawals()}catch(e){this.records=[];this.error=e.message||'提现记录加载失败'}finally{this.loading=false}},open(item){uni.navigateTo({url:'/pages/wallet/withdrawal-detail?id='+item.id})}}}</script>
<style scoped>.record-list{padding:24rpx 28rpx}.record-card{margin-bottom:16rpx;padding:25rpx 26rpx;display:flex;align-items:center;justify-content:space-between;border-radius:22rpx;background:var(--surface);box-shadow:var(--shadow-card)}.record-card>view{display:flex;flex-direction:column;gap:9rpx}.record-card{gap:20rpx;align-items:flex-start}.record-card>view:first-child{min-width:0;flex:1}.record-card>view:last-child{align-items:flex-end;flex-shrink:0;max-width:45%}.record-card .price{font-size:28rpx;overflow-wrap:anywhere}.record-no{overflow-wrap:anywhere;word-break:break-all;line-height:1.5}.record-no{font-size:24rpx;font-weight:700}.muted,.status{font-size:21rpx}.status{color:var(--muted)}.status-approved,.status-paid{color:#25a85a}.status-rejected{color:var(--primary)}</style>
